md = ["# Maryland / Talbot GIS source catalog",
"Verified 2026-10-11 by live `?f=json` and point queries. Machine-readable: `sources.json`. Point CLI: `02. Tools/gis_point_lookup.py`. Talbot extracts: `Talbot/Originals/Maps/`.\n",
"## How to query a parcel (lat/lon or address)",
"1. **Address -> point**: Geocoder (#4) `findAddressCandidates?SingleLine=...&outSR=4326`, or Talbot Address_Points (#33). Gives lon/lat.",
"2. **Parcel**: State parcel polygon (#1) point-intersect -> ACCTID, ACRES, land use, deed liber/folio. Optional owner history/sales/assessment: Socrata (#3) by JURSCODE+ACCTID; SDAT page link = `County=<first 2 of acct>&District=<next 2>&AccountNumber=<last 6>`.",
"3. **Zoning**: Talbot County zoning (#6) (authoritative; `Zoning2018`), plus overlays. Else MDP Generalized Zoning (#7). Ignore parcel ZONING field.",
"4. **Critical Area class**: Critical Area counties (#8) then towns (#9) -> Type IDA/LDA/RCA (no hit = outside the 1000-ft area).",
"5. **Septic tier**: MDP Septic Growth Tiers (#12) (Talbot local #13). **PFA**: #11. **W&S category**: Talbot sewer/water (#14/#15; no polygon = no planned service).",
"6. **Flood**: FEMA NFHL layer 28 (#21), fallback #22. **Wetlands**: DNR (#17, ignore Type=Upland), NWI (#18/#19), special state concern (#20). **Soils**: SDA SQL (#23) incl. hydric + septic limitation. Easements: #24-28; SLR: #30.",
"One command does all: `~/.venvs/esl/bin/python -I \"02. Tools/gis_point_lookup.py\" --lat 38.70 --lon -76.05 [--sdat] | --address \"...\"`.\n",
"## Access notes"]+[f"- {x}" for x in NOTES]
grp = {}
for c in C: grp.setdefault(c["group"], []).append(c)
for g, cs in grp.items():
    md += [f"\n## {g}\n", "| # | Layer | Publisher | Service URL / layer id | Geom | Key fields | Dates | Scope |", "|---|---|---|---|---|---|---|---|"]
    for c in cs:
        lid = f" / **{c['layer_id']}**" if c["layer_id"] is not None else ""
        md.append(f"| {c['n']} | {c['name']} | {c['publisher']} | `{c['service_url']}`{lid} | {c['geometry']} | {c['key_fields']} | {c['date_info']} | {c['scope']} |")
    for c in cs:
        md.append(f"\n**#{c['n']} example:** `{c['example_query']}`  ")
        if c["notes"]: md.append(f"Notes: {c['notes']}  ")
        if c["talbot_extract"]: md.append(f"Talbot extract: {c['talbot_extract']}")
files = sorted((ROOT/"Talbot/Originals/Maps").glob("*.geojson"))
md += ["\n## Talbot extracts downloaded (`Talbot/Originals/Maps/`, EPSG:4326, recorded in `Talbot/Manifest.csv`)\n", "| File | MB |", "|---|---|"]
md += [f"| {f.name} | {f.stat().st_size/1e6:.2f} |" for f in files]
md += ["\nNot downloaded by design (on-demand point queries only): FEMA NFHL, NWI, SSURGO, wetlands DNR, Green Infrastructure, forests, CRAB/SLAMM. Parcels were exported with trimmed fields and 6-decimal coordinates to stay under 50 MB.",
"Regenerate downloads: `02. Tools/gis_download_talbot.py [slug...]`; regenerate this catalog: `02. Tools/gis_build_catalog.py` (test outputs below are appended by gis_point_lookup tests)."]
(OUT/"SOURCES.md").write_text("\n".join(md)+"\n")
